import json,glob,re,sys
ids=set()
def load(root):
    out=[]
    for f in sorted(glob.glob(root+'/**/*.json',recursive=True)):
        if f.endswith('pack.json'): continue
        d=json.load(open(f)); out.append((f,d))
        for e in d['elements']:
            ids.add(e['id'])
            if 'multiclass' in e: ids.add(e['multiclass']['id'])
    return out
core=load('../../content/core'); srd=load('../../content/srd-5.2.1')
# generated by engine
gen=re.compile(r'^ID_INTERNAL_(CLASS_FEATURE_(ASI|FEAT)_|MAGIC_ITEM_SPELL_SCROLL_)')
miss={}
def walk(o,path,f,eid):
    if isinstance(o,dict):
        for k,v in o.items():
            if k in('maps_to','renamed_from','legacy_alias'): continue
            walk(v,path+[k],f,eid)
    elif isinstance(o,list):
        for v in o: walk(v,path,f,eid)
    elif isinstance(o,str):
        for t in re.findall(r'ID_[A-Z0-9_]{2,}',o):
            if t not in ids and not gen.match(t):
                miss.setdefault(t,[]).append((eid,'/'.join(map(str,path))))
for f,d in srd:
    for e in d['elements']:
        ee={k:v for k,v in e.items() if k not in('id',)}
        walk(ee,[],f,e['id'])
print('unresolved:',len(miss))
for t,l in sorted(miss.items()): print(t,len(l),l[0])
